/* Host test for ECDSA verify (docs/TLS.md T3). Vectors generated by Python's
 * `cryptography` with FIXED private keys (so they're reproducible): P-256/SHA-256
 * and P-384/SHA-384. Valid signatures must verify; a tampered r or a wrong hash
 * must be rejected. */
#include <stdio.h>
#include <string.h>
#include "ecdsa.h"

/* p256 */
static const uint8_t p256_qx[] = {0x7f,0x83,0x21,0xf4,0x06,0x47,0xed,0xa1,0x03,0x0e,0xc4,0x78,0x74,0x7e,0xa2,0x3d,0x2e,0x86,0xce,0xe3,0x2b,0xca,0x7b,0xa8,0x46,0x33,0x1e,0x11,0x15,0x98,0x16,0xe9};
