static const uint8_t p256_r[] = {0x3c,0x69,0x13,0xd8,0x62,0xda,0x24,0xb2,0x80,0xb6,0xe7,0xe1,0x5e,0x41,0xd5,0xab,0x19,0xf0,0x3f,0x79,0x7c,0x85,0xa7,0x15,0x08,0x84,0x66,0xd2,0xdc,0x60,0xc8,0x90};
static const uint8_t p256_s[] = {0xaa,0x7b,0x20,0x1c,0x14,0x0b,0x3a,0x61,0xfe,0x2e,0x48,0xcf,0x71,0x8c,0xca,0x45,0x77,0x35,0x9f,0xac,0x62,0xcf,0xb1,0x6b,0x34,0xaa,0xf0,0x3f,0xb3,0x84,0x5e,0x34};
/* p384 */
static const uint8_t p384_qx[] = {0x0e,0x17,0xea,0xee,0xd6,0x00,0x20,0xb9,0xf9,0x05,0x7f,0x80,0xf4,0x35,0x2a,0xc6,0x83,0x5c,0x7d,0x96,0x17,0xb4,0xca,0x9e,0x77,0x1e,0x3b,0xa7,0x05,0xb3,0x00,0xef,0x4b,0x5e,0x83,0xa1,0x67,0x08,0x06,0x38,0x39,0x91,0x22,0x77,0x77,0x16,0x74,0x25};
static const uint8_t p384_qy[] = {0x21,0x11,0x57,0x2e,0x9e,0xac,0xc5,0x01,0xdc,0xee,0x95,0x6e,0xf2,0x9c,0xaf,0xa6,0x04,0xfc,0x9f,0x52,0x3e,0x87,0x91,0x1f,0x22,0x3a,0x49,0xf3,0x7e,0xd2,0x9a,0xae,0x97,0xbd,0xfd,0xcc,0x96,0x8c,0x8e,0xd3,0x36,0x91,0x3b,0x58,0x1c,0xa8,0xcb,0x5f};
static const uint8_t p384_hash[] = {0x0c,0xee,0x45,0x07,0x00,0x5e,0x38,0x4d,0xa2,0x42,0x1d,0xcc,0x74,0xe5,0x28,0x33,0xe1,0xee,0x83,0xd8,0x2f,0x8b,0x30,0x53,0x93,0xf1,0x37,0xaf,0xba,0x55,0x5f,0x26,0xcd,0xd8,0x83,0x08,0x13,0x3f,0x4d,0x20,0xc8,0xee,0x75,0xbc,0x96,0x0b,0xbd,0xa7};
static const uint8_t p384_r[] = {0x0d,0xb1,0x01,0x69,0xb3,0x6f,0x9e,0x65,0xf9,0xed,0x08,0x53,0x9b,0xe5,0x89,0x5a,0x58,0x5a,0xf5,0x26,0xeb,0x7a,0x82,0xd4,0x56,0x97,0x0e,0xe9,0xe3,0x8c,0xe0,0xf0,0x00,0xc5,0xa6,0x3e,0x83,0xb8,0xa1,0x74,0x2b,0xae,0xb0,0x09,0x75,0x22,0xa2,0x4b};
static const uint8_t p384_s[] = {0x6d,0x3e,0x20,0x49,0x3c,0xb9,0xfe,0xe6,0xd4,0x92,0xe0,0x40,0xb8,0x2d,0x04,0x17,0xac,0x68,0xcc,0x04,0xdc,0xa5,0x2b,0xc0,0x12,0xa0,0x67,0x9a,0xa0,0x49,0x07,0x73,0xb5,0x0b,0x30,0xc3,0xe2,0x35,0xf7,0xfa,0x51,0x6d,0x5f,0x23,0x4d,0xd1,0xa5,0xca};

static int fails = 0;
#define CHECK(c, m) do { if (!(c)) { printf("  FAIL %s\n", m); fails++; } else printf("  ok   %s\n", m); } while (0)

int main(void) {
    printf("P-256 / SHA-256:\n");
    CHECK(ecdsa_verify(ec_p256(), p256_qx, p256_qy, p256_hash, 32, p256_r, 32, p256_s, 32) == 1,
          "valid signature verifies");
    { uint8_t bad[32]; memcpy(bad, p256_r, 32); bad[0] ^= 0x01;
      CHECK(ecdsa_verify(ec_p256(), p256_qx, p256_qy, p256_hash, 32, bad, 32, p256_s, 32) == 0,
            "tampered r rejected"); }
    { uint8_t bh[32]; memcpy(bh, p256_hash, 32); bh[31] ^= 0x01;
      CHECK(ecdsa_verify(ec_p256(), p256_qx, p256_qy, bh, 32, p256_r, 32, p256_s, 32) == 0,
            "wrong hash rejected"); }

    printf("P-384 / SHA-384:\n");
    CHECK(ecdsa_verify(ec_p384(), p384_qx, p384_qy, p384_hash, 48, p384_r, 48, p384_s, 48) == 1,
          "valid signature verifies");
    { uint8_t bad[48]; memcpy(bad, p384_s, 48); bad[47] ^= 0x01;
      CHECK(ecdsa_verify(ec_p384(), p384_qx, p384_qy, p384_hash, 48, p384_r, 48, bad, 48) == 0,
            "tampered s rejected"); }

    printf("\nECDSA verify (P-256 + P-384): %s\n", fails == 0 ? "ALL PASS" : "FAIL");
    return fails == 0 ? 0 : 1;
}
